### 2️⃣ JavaScript (`jigsaw.js`)

```js
const canvas=document.querySelector('#mainCanvas'),
ctx=canvas.getContext('2d');

let pieces=[],dragging=null,startTime=null,timerInterval;

// 初始化
document.getElementById('imgInput').addEventListener('change',e=>loadImg(e.target.files[0]));
initEvents();

function loadImg(file){ /* 同前文中的 sliceImage */ }

function initEvents(){ 
  canvas.addEventListener('mousedown',onMouseDown);
  canvas.addEventListener('mousemove',onMouseMove);
  canvas.addEventListener('mouseup',onMouseUp);
}

function startGame(){
  if(!imageLoaded)return alert("請先上傳圖片");
  pieces=sliceImage(imageObj,4,4); // 4×4 默認
  shuffleAndRender(); // 打亂後重新繪製
  startTimer();
}

function shuffleAndRender(){
  pieces.forEach(p=>{
    p.current={x: Math.random()*(canvas.width-p.imgW),
               y: Math.random()*(canvas.height-p.imgH)};
    p.snapped=false;
  });
  drawLoop();
}

function drawLoop(){
  ctx.clearRect(0,0,canvas.width,canvas.height);
  pieces.forEach(drawPiece);
  if(checkWin()) {alert(`恭喜！耗時 ${formatTime()} 秒`);}
  else setTimeout(drawLoop,30);
}

function drawPiece(piece){
  const img=new Image();
  img.src=piece.dataURL;
  img.onload=function(){
    ctx.save();
    ctx.translate(piece.current.x,piece.current.y);
    ctx.rotate(Math.PI/180*piece.rotation||0);
    ctx.drawImage(this,0,0,this.width*this.scale||this.width,this.height*this.scale||this.height);
    ctx.restore();
  };
}

/*** Drag‑and‑drop handlers ***/
function onMouseDown(ev){
  const pos=getCursorPos(ev);
  dragging=findTopmost(pos);
  if(dragging){dragOffsetX=pos.x-dragging.current.x;dragOffsetY=pos.y-dragging.current.y;}
}
function onMouseMove(ev){
  if(!dragging)return;
  const pos=getCursorPos(ev);
  dragging.current.x=pos.x-dragOffsetX;
  dragging.current.y=pos.y-dragOffsetY;
}
function onMouseUp(ev){
  if(!dragging)return;
  trySnap(dragging);
  dragging=null;
}
/*** Utility helpers ***/
function getCursorPos(evt){/*…*/}
function findTopmost(pt){/*…*/}
// 判斷是否貼合
function trySnap(piece){
  const dist=Math.hypot(piece.current.x-piece.target.x,piece.current.y-piece.target.y);
  if(dist<15){piece.current.x=piece.target.x;piece.current.y=piece.target.y;piece.snapped=true;}
}
function checkWin(){return pieces.every(p=>p.snapped);}

/*** Timer ***/
function startTimer(){startTime=Date.now(); timerInterval=setInterval(()=>updateTimer(),1000);}
function updateTimer(){ document.getElementById('timer').textContent=formatTime();}
function formatTime(){return ((Date.now()-startTime)/1000).toFixed(0);} 

```

> ⚡️這只是骨架代碼，具體細節如 `getCursorPos`, `findTopmost` 等需要自己填寫，但大致思路已呈現在上述框架裡。

